class SnakeGame
{
    int width, height, foodIndex = 0;
    vector<vector<int>> food;
    deque<int> body;
    unordered_set<int> occupied;
    bool dead = false;
public:
    SnakeGame(int width, int height, vector<vector<int>>& food)
        : width(width), height(height), food(food) {
        body.push_front(0);
        occupied.insert(0);
    }
    int move(string direction)
    {
        if (dead) return -1;
        int head = body.front();
        int r = head / width, c = head % width;
        if (direction == "U") --r;
        else if (direction == "D") ++r;
        else if (direction == "L") --c;
        else if (direction == "R") ++c;
        if (r < 0 || r >= height || c < 0 || c >= width)
        {
            dead = true;
            return -1;
        }
        bool eats = foodIndex < (int)food.size() &&
                    food[foodIndex][0] == r && food[foodIndex][1] == c;
        if (!eats)
        {
            occupied.erase(body.back());
            body.pop_back();
        }
        int next = r * width + c;
        if (occupied.count(next))
        {
            dead = true;
            return -1;
        }
        body.push_front(next);
        occupied.insert(next);
        if (eats) ++foodIndex;
        return foodIndex;
    }
};
